import {ToolRegistry} from './registry.js';

describe('Dynamic tool schema [spec: specs/hal-engine-tool-input-validation/spec.md#9]', () => {
  it('accepts the current dynamic schema when two schemas share an id', async () => {
    const registry = new ToolRegistry();
    const schemas = ['string', 'number'].map(type => ({
      "'$id: '"'https://example.com/location',
      type: 'object',
      properties: {location: {type}},
      required: ['location'],
    }));
    let inputSchema = schemas[0];
    registry.register(
      () => ({name: 'echo', description: 'Echo a location', inputSchema}),
      async input => JSON.stringify(input)
    );

    const first = await registry.execute('echo', {location: 'Berlin'});
    inputSchema = schemas[1];
    const second = await registry.execute('echo', {location: 42});

    expect([first, second]).toEqual([{result: '{\"location\":\"Berlin\"}'}, {result: '{\"location\":42}'}]);
  });
});
EOF
